// Runs only against the owned native PostgreSQL fixture. No adapter or fake response.
import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
import {randomUUID} from 'node:crypto';
setTimeout(()=>process.exit(124),55000).unref();
const {FaiberSDK}=await import(pathToFileURL(process.env.KNOWLEDGE_PACKED_FACADE).href);
const origin=process.env.KNOWLEDGE_OWNED_HTTP_ORIGIN;
assert.match(origin,/^http:\/\/127\.0\.0\.1:\d+$/);
const sdk=new FaiberSDK({domains:{knowledge:origin},axios:{timeout:5000,headers:{'x-organization-id':process.env.KNOWLEDGE_OWNED_ORGANIZATION,'x-user-permissions':'knowledge:*'}}});
const api=sdk.knowledge.operations,covered=new Set();let assertions=0;const statuses=new Map();
const eq=(a,b)=>{assert.deepEqual(a,b);assertions++;};
async function call(name,...args){const r=await api[name](...args).catch(e=>{throw Error(name+": "+e.response?.status+" "+JSON.stringify(e.response?.data));});covered.add(name);statuses.set(name,r.status);assert.ok(r.status>=200&&r.status<300);assertions++;return r.data?.data;}
async function denied(status,fn){await assert.rejects(fn,e=>{eq(e.response?.status,status);return true;});}
const base=await call('routesCreateBasePost',{slug:'packed-'+randomUUID(),name:'Owned packed SDK'});
eq(base.version,1);eq(base.published_release_id,null);
eq((await call('routesGetBaseGet',base.id)).id,base.id);
eq((await call('routesListBasesGet',{q:base.slug,limit:1}))[0].id,base.id);
const edited=await call('routesUpdateBasePut',base.id,{name:'Revised',expected_version:1});eq(edited.version,2);
await denied(409,()=>api.routesUpdateBasePut(base.id,{name:'stale',expected_version:1}));
await denied(403,()=>api.routesCreateBasePost({slug:'denied',name:'Denied'},{headers:{'x-user-permissions':'knowledge:read'}}));
await denied(404,()=>api.routesGetBaseGet(base.id,{headers:{'x-organization-id':randomUUID()}}));
const group=await call('routesCreateGroupPost',base.id,{slug:'group',name:{en:'Group',fa:'گروه'}});eq(group.level,0);
eq((await call('routesListGroupsGet',base.id))[0].id,group.id);
eq((await call('routesUpdateGroupPut',group.id,{sort_order:2,expected_version:1})).version,2);
const itemInput={group_id:group.id,kind:'fact',title:{en:'Fact'},content:{en:'Owned evidence'},linked_service:'infera-lms',linked_entity_type:'course',linked_entity_id:'owned-course',description:{fa:'شرح'},open_in_new_tab:true};
const a=await call('routesCreateItemPost',base.id,{...itemInput,slug:'one'}),b=await call('routesCreateItemPost',base.id,{...itemInput,slug:'two'});
eq(a.linked_entity_id,'owned-course');eq(a.deleted_at,null);eq(a.open_in_new_tab,true);
eq((await call('routesGetItemGet',a.id)).id,a.id);
eq((await call('routesListItemsGet',base.id,{q:'one',limit:1}))[0].id,a.id);
eq((await call('routesUpdateItemPut',a.id,{importance:'warning',expected_version:1})).version,2);
await denied(400,()=>api.routesUpdateItemPut(a.id,{importance:'high',expected_version:2}));
const edge=await call('routesCreateEdgePost',base.id,{from_item_id:a.id,to_item_id:b.id,edge_type:'related'});
eq((await call('routesListEdgesGet',base.id))[0].id,edge.id);
eq((await call('routesUpdateEdgePut',edge.id,{weight:2,expected_version:1})).weight,2);
await denied(409,()=>api.routesDeleteItemDelete(a.id));
const binding=await call('routesCreateBindingPost',{knowledge_base_id:base.id,chat_slug:'owned-'+randomUUID()});
assert.ok((await call('routesListBindingsGet')).some(x=>x.id===binding.id));assertions++;
eq((await call('routesUpdateBindingPut',binding.id,{enabled:false,expected_version:1})).enabled,false);
const rule=await call('routesCreateRulePost',{knowledge_base_id:base.id,group_id:group.id,slug:'packed-rule',name:{en:'Rule'},conditions:{path:'profile.active',op:'eq',value:true},outcomes:[]});
eq((await call('routesUpdateRulePut',rule.id,{enabled:false,expected_version:1})).enabled,false);
const filtered=await api.routesListRulesGet({knowledge_base_id:base.id,group_id:group.id,q:'packed-rule',enabled:false,page:1,limit:1});covered.add('routesListRulesGet');
eq(filtered.data.meta,{total:1,page:1,limit:1});eq(filtered.data.data[0].id,rule.id);
const convenience=await sdk.knowledge.matchRules({knowledge_base_id:base.id,enabled:false});eq(convenience.data.meta.total,1);
await denied(409,()=>api.routesDeleteGroupDelete(group.id));
const release=await call('routesPublishPost',base.id);eq(release.knowledge_base_id,base.id);assert.match(release.checksum_sha256,/^[a-f0-9]{64}$/);assertions++;
eq((await call('routesGetReleaseGet',release.id)).checksum_sha256,release.checksum_sha256);
eq((await sdk.knowledge.release(release.id)).data.data.id,release.id);
eq((await call('routesExportBaseGet',base.id)).knowledge_base.id,base.id);

const source=await call('platformCreateSourcePost',{knowledge_base_id:base.id,slug:'packed-source',name:{en:'Owned manual source'},source_type:'manual'});
assert.ok((await call('platformListSourcesGet')).some(x=>x.id===source.id));assertions++;
const sync=await call('platformSyncSourcePost',source.id);eq(statuses.get('platformSyncSourcePost'),202);
const syncRetry=await call('platformSyncSourcePost',source.id);eq(syncRetry.job_id,sync.job_id);
const paused=await call('platformPauseSourcePost',source.id);eq(paused.status,'paused');eq(paused.version,source.version+1);
await denied(409,()=>api.platformSyncSourcePost(source.id));
const resumed=await call('platformPauseSourcePost',source.id);eq(resumed.status,'active');eq(resumed.version,paused.version+1);

const documentInput={knowledge_base_id:base.id,external_id:'packed-'+randomUUID(),title:'Owned document',content:'Owned durable source text.'};
const indexed=await call('platformIngestDocumentPost',documentInput);eq(statuses.get('platformIngestDocumentPost'),201);eq(indexed.status,'indexed');assert.match(indexed.job_id,/^[a-f0-9-]{36}$/);assertions++;
const unchanged=await call('platformIngestDocumentPost',documentInput);eq(statuses.get('platformIngestDocumentPost'),200);eq(unchanged.status,'unchanged');eq(unchanged.id,indexed.id);eq(unchanged.job_id,undefined);
const documents=await call('platformListDocumentsGet');const document=documents.find(x=>x.id===indexed.id);assert.ok(document);assertions++;eq(document.checksum,undefined);eq(document.metadata,undefined);eq(document.source_id,null);assert.ok(document.indexed_at);assertions++;
eq((await sdk.knowledge.ingestDocument(documentInput)).data.data.status,'unchanged');
const corrected=await call('platformIngestDocumentPost',{...documentInput,title:'Corrected title',provenance:{source_revision:'owned-correction'}});eq(statuses.get('platformIngestDocumentPost'),201);eq(corrected.id,indexed.id);
const correctedList=await call('platformListDocumentsGet');eq(correctedList.find(x=>x.id===indexed.id).title,'Corrected title');eq(correctedList.find(x=>x.id===indexed.id).provenance,{source_revision:'owned-correction'});
const parallelInput={...documentInput,external_id:'parallel-'+randomUUID()};
const parallel=await Promise.all([1,2,3].map(()=>api.platformIngestDocumentPost(parallelInput)));eq(parallel.map(x=>x.status).sort(),[200,200,201]);eq(new Set(parallel.map(x=>x.data.data.id)).size,1);

await denied(404,()=>api.platformIngestDocumentPost(documentInput,{headers:{'x-organization-id':randomUUID()}}));
await denied(400,()=>api.platformIngestDocumentPost({...documentInput,source_id:randomUUID()}));
await denied(500,()=>api.platformIngestDocumentPost({...documentInput,external_id:'fault-'+randomUUID(),title:'owned-job-fault'}));
const afterFault=await call('platformListDocumentsGet');eq(afterFault.some(x=>x.title==='owned-job-fault'),false);
const auditFault=await call('platformIngestDocumentPost',{...documentInput,external_id:'audit-fault-'+randomUUID(),title:'owned-audit-fault'});
await denied(500,()=>api.platformReprocessDocumentPost(auditFault.id));
const faultJobs=await api.platformProcessingJobsGet();covered.add('platformProcessingJobsGet');eq(faultJobs.data.data.some(x=>x.document_id===auditFault.id&&x.job_type==='document_reprocess'),false);
const reprocess=await call('platformReprocessDocumentPost',indexed.id);eq(statuses.get('platformReprocessDocumentPost'),202);
const replay=await call('platformReprocessDocumentPost',indexed.id);eq(replay.job_id,reprocess.job_id);
const jobs=await sdk.knowledge.processingJobs();assert.ok(jobs.data.data.some(x=>x.id===reprocess.job_id));assertions++;
assert.ok((await call('platformAuditEventsGet')).length>0);assertions++;

const before=release.manifest.items;
await call('routesDeleteEdgeDelete',edge.id);await call('routesDeleteBindingDelete',binding.id);await call('routesDeleteRuleDelete',rule.id);
await call('routesDeleteItemDelete',a.id);await call('routesDeleteItemDelete',b.id);await call('routesDeleteGroupDelete',group.id);
eq((await call('routesGetReleaseGet',release.id)).manifest.items,before);
const actions=await call('workspaceAssistantContracts',{status:'open',limit:10});eq(actions.length,1);eq(actions[0].id,process.env.KNOWLEDGE_OWNED_ACTION);
eq((await call('routesUpdateActionStatusPatch',actions[0].id,{status:'completed',input:{choice:'done'}})).status,'completed');
await denied(400,()=>api.routesUpdateActionStatusPatch(actions[0].id,{status:'invalid'}));
assert.ok((await call('routesListAuditGet',{limit:200})).length>0);assertions++;
await call('routesDeleteBaseDelete',base.id);await denied(404,()=>api.routesGetBaseGet(base.id));
eq(covered.size,41);
console.log(JSON.stringify({status:'passed',assertions,covered_exports:[...covered].sort(),boundary:'actual_packed_typescript_sdk_http_postgresql',identity_limit:'explicit trusted fixture headers, not current IDP/gateway authentication'}));
